    def test_no_formula_errors(self):
        """Verify no #VALUE!, #REF!, #NAME?, etc. errors in calculated cells."""
        csv_data = load_csv_data()

        excel_errors = ["#VALUE!", "#DIV/0!", "#REF!", "#NAME?", "#NULL!", "#NUM!", "#N/A"]
        error_cells = []

        # Check all relevant ranges
        ranges_to_check = [
            (12, 18),  # Exports
            (19, 25),  # Imports
            (26, 32),  # GDP
            (35, 41),  # Net exports %
            (42, 48),  # Statistics
            (50, 51),  # Weighted mean
        ]

        for start_row, end_row in ranges_to_check:
            for row in range(start_row, end_row):
                for col in COLUMNS:
                    cell = f"{col}{row}"
                    val = csv_data.get(cell)
                    if val is not None and isinstance(val, str):
                        for err in excel_errors:
                            if err in str(val):
                                error_cells.append(f"{cell}: {val}")
                                break

        # Also check xlsx
        wb = get_workbook()
        ws = get_task_sheet(wb)
        for start_row, end_row in ranges_to_check:
            for row in range(start_row, end_row):
                for col in COLUMNS:
                    cell = f"{col}{row}"
                    val = ws[cell].value
                    if val is not None and isinstance(val, str):
                        for err in excel_errors:
                            if err in str(val):
                                if f"{cell}:" not in str(error_cells):
                                    error_cells.append(f"{cell}: {val}")
                                break
        wb.close()

